"""Read session-tracker JSON files for usage, cost, and quota data.

Session-tracker files are written by the my-claude-stuff hook into
~/.claude/my-claude-stuff-data/session-tracker/<YYYY-MM-DD>/<session-id>.json.
This module provides read-only access to that data.
"""

import json
import logging
import time
from dataclasses import dataclass
from datetime import date
from pathlib import Path

logger = logging.getLogger(__name__)

SESSION_TRACKER_ROOT = (
    Path.home() / ".claude" / "my-claude-stuff-data" / "session-tracker"
)


@dataclass
class SessionData:
    """Parsed session-tracker data for one Claude Code session."""

    session_id: str
    cwd: str
    model_id: str
    model_display_name: str
    total_cost_usd: float
    total_duration_ms: int
    total_api_duration_ms: int
    lines_added: int
    lines_removed: int
    total_input_tokens: int
    total_output_tokens: int
    context_used_pct: int
    five_hour_pct: int
    five_hour_resets_at: int | None
    seven_day_pct: int
    seven_day_resets_at: int | None


@dataclass
class AggregateData:
    """Aggregated metrics across multiple sessions."""

    session_count: int
    total_cost_usd: float
    total_input_tokens: int
    total_output_tokens: int
    total_lines_added: int
    total_lines_removed: int
    max_five_hour_pct: int
    max_seven_day_pct: int
    earliest_five_hour_reset: int | None
    earliest_seven_day_reset: int | None


def parse_session_file(path: Path) -> SessionData | None:
    """Parse a single session-tracker JSON file.

    Returns None if the file can't be read or parsed.
    """
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as e:
        logger.warning("Skipping %s: %s", path.name, e)
        return None

    model = data.get("model", {})
    cost = data.get("cost", {})
    ctx = data.get("context_window", {})
    limits = data.get("rate_limits", {})
    five_h = limits.get("five_hour", {})
    seven_d = limits.get("seven_day", {})

    return SessionData(
        session_id=data.get("session_id", path.stem),
        cwd=data.get("cwd", ""),
        model_id=model.get("id", "unknown"),
        model_display_name=model.get("display_name", "unknown"),
        total_cost_usd=cost.get("total_cost_usd") or 0.0,
        total_duration_ms=cost.get("total_duration_ms") or 0,
        total_api_duration_ms=cost.get("total_api_duration_ms") or 0,
        lines_added=cost.get("total_lines_added") or 0,
        lines_removed=cost.get("total_lines_removed") or 0,
        total_input_tokens=ctx.get("total_input_tokens") or 0,
        total_output_tokens=ctx.get("total_output_tokens") or 0,
        context_used_pct=int(ctx.get("used_percentage") or 0),
        five_hour_pct=int(five_h.get("used_percentage") or 0),
        five_hour_resets_at=five_h.get("resets_at"),
        seven_day_pct=int(seven_d.get("used_percentage") or 0),
        seven_day_resets_at=seven_d.get("resets_at"),
    )


def _normalize_path(p: str) -> str:
    """Normalize a path string for comparison (lowercase, forward slashes)."""
    return p.replace("\\", "/").lower()


def load_sessions(
    target_date: date,
    *,
    tracker_root: Path = SESSION_TRACKER_ROOT,
    cwd_filter: str | None = None,
) -> list[SessionData]:
    """Load all session-tracker files for a given date.

    Args:
        target_date: Which date directory to read.
        tracker_root: Override root for testing.
        cwd_filter: If set, only return sessions whose cwd matches
            (normalized case-insensitive, forward-slash comparison).

    Returns:
        List of SessionData sorted by session_id.
    """
    day_dir = tracker_root / target_date.isoformat()
    if not day_dir.is_dir():
        return []

    sessions: list[SessionData] = []
    norm_filter = _normalize_path(cwd_filter) if cwd_filter else None

    for f in day_dir.glob("*.json"):
        session = parse_session_file(f)
        if session is None:
            continue
        if norm_filter and _normalize_path(session.cwd) != norm_filter:
            continue
        sessions.append(session)

    sessions.sort(key=lambda s: s.session_id)
    return sessions


def aggregate(sessions: list[SessionData]) -> AggregateData:
    """Compute aggregate metrics from a list of sessions."""
    if not sessions:
        return AggregateData(
            session_count=0,
            total_cost_usd=0.0,
            total_input_tokens=0,
            total_output_tokens=0,
            total_lines_added=0,
            total_lines_removed=0,
            max_five_hour_pct=0,
            max_seven_day_pct=0,
            earliest_five_hour_reset=None,
            earliest_seven_day_reset=None,
        )

    five_h_resets = [
        s.five_hour_resets_at for s in sessions if s.five_hour_resets_at is not None
    ]
    seven_d_resets = [
        s.seven_day_resets_at for s in sessions if s.seven_day_resets_at is not None
    ]

    return AggregateData(
        session_count=len(sessions),
        total_cost_usd=sum(s.total_cost_usd for s in sessions),
        total_input_tokens=sum(s.total_input_tokens for s in sessions),
        total_output_tokens=sum(s.total_output_tokens for s in sessions),
        total_lines_added=sum(s.lines_added for s in sessions),
        total_lines_removed=sum(s.lines_removed for s in sessions),
        max_five_hour_pct=max(s.five_hour_pct for s in sessions),
        max_seven_day_pct=max(s.seven_day_pct for s in sessions),
        earliest_five_hour_reset=min(five_h_resets) if five_h_resets else None,
        earliest_seven_day_reset=min(seven_d_resets) if seven_d_resets else None,
    )


def format_cost(usd: float) -> str:
    """Format USD cost for display."""
    if usd < 0.01 and usd > 0:
        return f"${usd:.3f}"
    return f"${usd:.2f}"


def format_tokens(count: int) -> str:
    """Format token count with K/M suffix."""
    if count >= 1_000_000:
        return f"{count / 1_000_000:.1f}M"
    if count >= 1000:
        return f"{count / 1000:.1f}K".replace(".0K", "K")
    return str(count)


def format_duration_compact(ms: int) -> str:
    """Format milliseconds as compact duration."""
    total_s = ms // 1000
    if total_s < 60:
        return f"{total_s}s"
    minutes = total_s // 60
    if minutes < 60:
        return f"{minutes}m"
    hours = minutes // 60
    remaining_m = minutes % 60
    return f"{hours}h{remaining_m}m"


def format_reset_time(resets_at: int | None) -> str:
    """Format a reset timestamp as time remaining."""
    if resets_at is None:
        return ""
    remaining = resets_at - int(time.time())
    if remaining <= 0:
        return "0s"
    if remaining < 60:
        return f"{remaining}s"
    minutes = remaining // 60
    if minutes < 60:
        return f"{minutes}m"
    hours = minutes // 60
    remaining_m = minutes % 60
    return f"{hours}h{remaining_m}m"
